                                style={styles.link}
                                onPress={() => {
                                    Link.openExternalLink(CONST.SAGE_INTACCT_INSTRUCTIONS);
                                }}
                            >
                                {translate('workspace.intacct.detailedInstructionsLink')}
                            </TextLink>
                            <Text>{translate('workspace.intacct.detailedInstructionsRestOfSentence')}</Text>
                        </Text>
                    </View>
